1	package nexusbench
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7	)
8	
9	// recycleUpstreamStorage empties the upstream registry by replacing its claim:
10	// the upstream is cut, the claim bench-upstream-data (and nothing else) is
11	// deleted once its label is checked, recreated from its manifest alone, and the
12	// upstream is brought back to one ready replica. The delete is sent once and never
13	// retried; the wait for the claim to be gone lasts until Params.DeleteTimeout.
14	// Like CutUpstream, it runs no preflight (the caller runs OpReset), refuses a
15	// custom upstream before any call, returns a cancelled context as is and accepts
16	// a nil out. A claim that is already gone is not deleted again, so a run that
17	// stopped between the delete and the apply starts again where it stopped.
18	func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
19		if out == nil {
20			out = io.Discard
21		}
22		if err := CutUpstream(ctx, r, clk, p, out); err != nil {
23			return err
24		}
25		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
26		if err := d.deleteUpstreamClaim(ctx); err != nil {
27			return err
28		}
29		claim, err := renderUpstreamClaim(p)
30		if err != nil {
31			return err
32		}
33		d.say("creating the claim %s again", upstreamClaimName)
34		if err := d.apply(ctx, "the claim "+upstreamClaimName, claim); err != nil {
35			return err
36		}
37		return EnsureUpstream(ctx, r, clk, p, out)
38	}
39	
40	// deleteUpstreamClaim deletes the claim of the upstream, once its label proves
41	// the bench created it, and waits until it is gone. A claim that is not there is
42	// left as it is.
43	func (d *deployer) deleteUpstreamClaim(ctx context.Context) error {
44		labels, found, err := d.readUpstreamClaim(ctx)
45		if err != nil || !found {
46			return err
47		}
48		p := d.pf.p
49		if labels[managedByLabel] != managedByValue {
50			return &BenchError{
51				Kind:  Unclassified,
52				Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it and will not delete it", upstreamClaimName, managedByLabel, managedByValue),
53				Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", p.Namespace, "--show-labels"),
54			}
55		}
56		d.say("deleting the claim %s", upstreamClaimName)
57		args := []string{"delete", "pvc", upstreamClaimName, "-n", p.Namespace, "--wait=false", applyTimeout}
58		if _, errOut, err := d.pf.r.Run(ctx, nil, args...); err != nil {
59			if cerr := ctx.Err(); cerr != nil {
60				return cerr
61			}
62			return d.pf.failure("delete the claim "+upstreamClaimName, args, string(errOut), err)
63		}
64		return d.waitUpstreamClaimGone(ctx)
65	}
66	
67	// readUpstreamClaim reads the claim of the upstream by name; found is false when
68	// it is not there.
69	func (d *deployer) readUpstreamClaim(ctx context.Context) (labels map[string]string, found bool, err error) {
70		var claim struct {
71			Metadata struct {
72				Labels map[string]string `json:"labels"`
73			} `json:"metadata"`
74		}
75		args := []string{"get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "-o", "json"}
76		found, err = d.fetch(ctx, "read the claim "+upstreamClaimName, args, &claim, true)
77		return claim.Metadata.Labels, found, err
78	}
79	
80	// waitUpstreamClaimGone polls the claim until it is not there, or until
81	// Params.DeleteTimeout passes. Like the other waits, it looks at the deadline
82	// after a reading.
83	func (d *deployer) waitUpstreamClaimGone(ctx context.Context) error {
84		p := d.pf.p
85		deadline := d.clk.Now().Add(p.DeleteTimeout)
86		for {
87			_, found, err := d.readUpstreamClaim(ctx)
88			if err != nil || !found {
89				return err
90			}
91			if !d.clk.Now().Before(deadline) {
92				return &BenchError{
93					Kind:  Deadline,
94					Cause: fmt.Sprintf("the claim %s is still terminating after %s: a finalizer (kubernetes.io/pvc-protection) may hold it", upstreamClaimName, p.DeleteTimeout),
95					Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", p.Namespace, "-o", "yaml"),
96				}
97			}
98			if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
99				return err
100			}
101		}
102	}
