298	// push copies images[i] from the layout to dst unless dst already holds the
299	// digest of the data set. A proven absence (errImageAbsent) is a copy; any
300	// other failure to read stops the seed.
301	func (s *seeder) push(i int, dst ImageRef, creds *Credentials, where string) error {
302		img := s.images[i]
303		name := img.Name + ":" + img.Tag
304		have, err := s.d.Copier.ManifestDigest(s.ctx, dst, creds)
305		if errors.Is(err, errImageAbsent) {
306			have, err = "", nil
307		}
308		if err != nil {
309			return s.failure(err, "reading "+name+" in "+where)
310		}
311		if have == img.Digest {
312			s.say("%s is already in %s", name, where)
313			return nil
314		}
315		s.say("copying %s to %s", name, where)
316		err = s.d.Copier.Copy(s.ctx, s.source(i), dst, CopyOptions{DestCreds: creds, PreserveDigests: true})
317		if err != nil {
318			return s.failure(err, "copying "+name+" to "+where)
319		}
320		return nil
321	}
