323	// pullThrough has docker-proxy pull each PullThrough image from the upstream
324	// with the bench-pull account, into a folder that is thrown away. Only these
325	// images are ever read through the proxy (F9): it caches whatever it serves. An
326	// image the proxy already lists with the right digest is not pulled again.
327	func (s *seeder) pullThrough(root string) error {
328		cached, err := s.c.listComponents(s.ctx, dockerProxyRepository)
329		if err != nil {
330			return s.restFailure(err)
331		}
332		for i, img := range s.images {
333			if !img.PullThrough {
334				continue
335			}
336			name := img.Name + ":" + img.Tag
337			if listed(cached, img) {
338				s.say("%s is already cached by %s", name, dockerProxyRepository)
339				continue
340			}
341			s.say("pulling %s through %s", name, dockerProxyRepository)
342			dst := ImageRef{Transport: "dir", Location: filepath.Join(root, fmt.Sprintf("pull-%02d", i+1))}
343			src := nexusImageRef(s.p, dockerProxyRepository, img)
344			if err := s.d.Copier.Copy(s.ctx, src, dst, CopyOptions{SrcCreds: &s.pull, PreserveDigests: true}); err != nil {
345				return s.failure(err, "pulling "+name+" through "+dockerProxyRepository)
346			}
347		}
348		return nil
349	}
