363	// verify waits, for at most seedListWait, until repo lists every image of want
364	// and nothing else (H-COMPONENTS). A component outside the data set cannot be
365	// waited away: it fails at once and asks for a reset.
366	func (s *seeder) verify(repo string, want []DatasetImage) error {
367		deadline := s.d.Clock.Now().Add(seedListWait)
368		for {
369			comps, err := s.c.listComponents(s.ctx, repo)
370			if err != nil {
371				return s.restFailure(err)
372			}
373			if extra := outside(comps, want); len(extra) > 0 {
374				return &BenchError{
375					Kind:  SeedFailed,
376					Cause: fmt.Sprintf("%s holds images outside the dataset (%s)", repo, shownNames(extra)),
377					Check: resetCheck,
378				}
379			}
380			missing := absent(comps, want)
381			if len(missing) == 0 {
382				s.say("%s lists the %d images of the data set", repo, len(want))
383				return nil
384			}
385			if !s.d.Clock.Now().Before(deadline) {
386				return &BenchError{
387					Kind:  SeedFailed,
388					Cause: fmt.Sprintf("%s does not list %s after %s", repo, strings.Join(missing, ", "), seedListWait),
389					Check: "run the seed again, and read the log of the pod if it persists: " + podsCommand(s.p),
390				}
391			}
392			if err := s.d.Clock.Sleep(s.ctx, seedListInterval); err != nil {
393				return err
394			}
395		}
396	}
