398	// shownNames quotes the names a listing returned, so that an escape sequence of
399	// a terminal shows as text, and prints at most maxSeedNamesShown of them: the
400	// rest is summed up as "and K more" (F3 of the audit).
401	func shownNames(names []string) string {
402		shown := names[:min(len(names), maxSeedNamesShown)]
403		quoted := make([]string, len(shown))
404		for i, n := range shown {
405			quoted[i] = strconv.Quote(n)
406		}
407		out := strings.Join(quoted, ", ")
408		if more := len(names) - len(shown); more > 0 {
409			out += fmt.Sprintf(" and %d more", more)
410		}
411		return out
412	}
