414	// outside lists the "name:tag" of the components that are not in want.
415	func outside(components []component, want []DatasetImage) []string {
416		var out []string
417		for _, comp := range components {
418			known := false
419			for _, img := range want {
420				known = known || (comp.Name == img.Name && comp.Version == img.Tag)
421			}
422			if !known {
423				out = append(out, comp.Name+":"+comp.Version)
424			}
425		}
426		return out
427	}
