351	// listed reports whether components hold img: its name and tag are enough, a
352	// component the instance lists without a digest counts as present (H-COMPONENTS),
353	// and a digest it does list must be the one of the data set.
354	func listed(components []component, img DatasetImage) bool {
355		for _, comp := range components {
356			if comp.Name == img.Name && comp.Version == img.Tag {
357				return comp.Digest == "" || comp.Digest == img.Digest
358			}
359		}
360		return false
361	}
