429	// absent lists the "name:tag" of the images of want that components do not list
430	// with the right digest.
431	func absent(components []component, want []DatasetImage) []string {
432		var out []string
433		for _, img := range want {
434			if !listed(components, img) {
435				out = append(out, img.Name+":"+img.Tag)
436			}
437		}
438		return out
439	}
