264	// firstLogin changes the initial admin REDACTED of the pod. The new REDACTED is
265	// stored as pending before it is sent, and promoted once the instance has it.
266	func (pv *provisioner) firstLogin(ctx context.Context) (*client, error) {
267		initial, ok, err := pv.ip.Read(ctx)
268		if err != nil {
269			return nil, pv.fail("the initial admin REDACTED could not be read from the pod", "check that the pod is running: "+podsCommand(pv.p), err)
270		}
271		if !ok || initial == "" {
272			return nil, pv.adminUnknown()
273		}
274		accepted, err := pv.adminAccepts(ctx, initial)
275		if err != nil {
276			return nil, err
277		}
278		if !accepted {
279			return nil, pv.adminUnknown()
280		}
281	
282		next := pv.secrets.PendingAdminPassword
283		if next == "" {
284			if next, err = generatePassword(); err != nil {
285				return nil, pv.fail("a REDACTED could not be generated", "check the operating system's random source", err)
286			}
287			pv.secrets.PendingAdminPassword = next
288			if err := pv.saveSecrets("the new admin REDACTED could not be stored, so the admin REDACTED was not changed"); err != nil {
289				return nil, err
290			}
291		}
292		first := newClient(pv.base, adminUserID, initial)
293		defer first.closeIdle()
294		if err := changePassword(ctx, first, adminUserID, next); err != nil {
295			return nil, err
296		}
297		pv.secrets.AdminPassword, pv.secrets.PendingAdminPassword = next, ""
298		if err := pv.saveSecrets("the admin REDACTED was changed but the secrets file could not be updated; it still holds the new REDACTED as pending"); err != nil {
299			return nil, err
300		}
301		pv.say("the admin REDACTED was changed")
302		return newClient(pv.base, adminUserID, next), nil
303	}
