966	// serveComponents lists the components of one repository, a page at a time. The
967	// token is the offset of the next page behind an opaque prefix; the last page
968	// carries "continuationToken": null, as Nexus does.
969	func (f *fakeNexus) serveComponents(w http.ResponseWriter, r *http.Request) {
970		if r.Method != http.MethodGet {
971			f.reply(w, r, http.StatusMethodNotAllowed, nil)
972			return
973		}
974		q := r.URL.Query()
975		repo := q.Get("repository")
976		if repo == "" {
977			f.badRequest(w, r, "the repository parameter is required")
978			return
979		}
980		if !f.repoExists(repo) {
981			f.reply(w, r, http.StatusNotFound, nil)
982			return
983		}
984		if left, stale := f.staleReads[repo]; stale {
985			if left <= 0 {
986				delete(f.staleReads, repo)
987				delete(f.components, repo)
988			} else {
989				f.staleReads[repo] = left - 1
990			}
991		}
992		offset := 0
993		if token := q.Get("continuationToken"); token != "" {
994			if f.laterPageFails != 0 {
995				f.reply(w, r, f.laterPageFails, map[string]any{"message": "injected fault"})
996				return
997			}
998			n, ok := strings.CutPrefix(token, componentTokenPrefix)
999			if !ok {
1000				f.badRequest(w, r, "unknown continuation token")
1001				return
1002			}
1003			digits, _, _ := strings.Cut(n, "/")
1004			parsed, err := strconv.Atoi(digits)
1005			if err != nil || parsed < 0 {
1006				f.badRequest(w, r, "unknown continuation token")
1007				return
1008			}
1009			offset = parsed
1010		}
1011		all := f.components[repo]
1012		end := min(offset+f.componentPage, len(all))
1013		offset = min(offset, end)
1014		items := make([]any, 0, end-offset)
1015		for _, c := range all[offset:end] {
1016			items = append(items, c.payload(repo))
1017		}
1018		var token any // null on the last page
1019		if end < len(all) {
1020			token = componentTokenPrefix + strconv.Itoa(end) + "/=&?"
1021		} else if f.loopTokens[repo] {
1022			token = componentTokenPrefix + "0/=&?"
1023		}
1024		f.reply(w, r, http.StatusOK, map[string]any{"items": items, "continuationToken": token})
1025	}
