263	func (c *seedCopier) lookup(ref ImageRef) (refInfo, bool) {
264		if c.index == nil {
265			c.index = map[string]refInfo{}
266			for _, img := range Dataset() {
267				switch img.Location {
268				case LocationHosted:
269					c.index[imageArg(nexusImageRef(*c.p, dockerHostedRepository, img))] = refInfo{whereHosted, img}
270				case LocationUpstream:
271					c.index[imageArg(upstreamImageRef(c.fwd.local, img))] = refInfo{whereUpstream, img}
272					c.index[imageArg(nexusImageRef(*c.p, dockerProxyRepository, img))] = refInfo{whereProxy, img}
273				}
274			}
275		}
276		info, ok := c.index[imageArg(ref)]
277		return info, ok
278	}
