319	// read returns the manifest digest of ref the way a registry (or a layout) would.
320	func (c *seedCopier) read(ref ImageRef, creds *Credentials) (string, error) {
321		if ref.Transport == "oci" {
322			return c.readLayout(ref)
323		}
324		info, ok := c.lookup(ref)
325		if !ok || ref.Transport != "docker" {
326			c.t.Errorf("read of %s: not a reference of the data set", imageArg(ref))
327			return "", c.absent()
328		}
329		if err := c.reach(info.where); err != nil {
330			return "", err
331		}
332		if err := c.authorize(info.where, creds); err != nil {
333			return "", err
334		}
335		nt := nameTag(info.img)
336		switch info.where {
337		case whereUpstream:
338			if d, ok := c.upstream[nt]; ok {
339				return d, nil
340			}
341		case whereHosted:
342			if d, ok := c.hosted[nt]; ok {
343				return d, nil
344			}
345		case whereProxy:
346			if !info.img.PullThrough {
347				c.t.Errorf("F9: %s was read through docker-proxy, which caches it: only PullThrough images may be", nt)
348			}
349			if d, ok := c.proxyCache[nt]; ok {
350				return d, nil
351			}
352			if d, ok := c.upstream[nt]; ok {
353				c.preload(whereProxy, info.img, d)
354				return d, nil
355			}
356		}
357		return "", c.absent()
358	}
