527		comp := fakeComponent{Name: img.Name, Version: img.Tag, Digest: digest}
528		list := c.listing[repo]
529		if i := slices.IndexFunc(list, func(x fakeComponent) bool { return x.Name == comp.Name && x.Version == comp.Version }); i >= 0 {
530			list[i] = comp
531		} else {
532			list = append(list, comp)
533		}
534		c.listing[repo] = list
