236	// absentManifestText is what skopeo prints for an image that is not there.
237	const absentManifestText = textManifestUnknown
238	
239	// absent is the error ManifestDigest returns for an image that is not in the
240	// registry: built from the output of skopeo by the code of the real copier, not
241	// from a kind. absentText (default: manifest unknown) says which output.
242	func (c *seedCopier) absent() error {
243		text := c.absentText
244		if text == "" {
245			text = absentManifestText
246		}
247		return inspectFailure(text, errFakeExit1)
248	}
