493	// preload puts an image, with a digest, in a registry as an earlier run left it.
494	func (c *seedCopier) preload(where string, img DatasetImage, digest string) {
495		nt := nameTag(img)
496		switch where {
497		case whereUpstream:
498			c.upstream[nt] = digest
499		case whereHosted:
500			c.hosted[nt] = digest
501			c.setComponent(dockerHostedRepository, img, digest)
502		case whereProxy:
503			c.proxyCache[nt] = digest
504			c.setComponent(dockerProxyRepository, img, digest)
505		}
506	}
