508	// preloadAll is the registries as a complete seed leaves them.
509	func (c *seedCopier) preloadAll() {
510		for _, img := range Dataset() {
511			switch img.Location {
512			case LocationHosted:
513				c.preload(whereHosted, img, img.Digest)
514			case LocationUpstream:
515				c.preload(whereUpstream, img, img.Digest)
516				if img.PullThrough {
517					c.preload(whereProxy, img, img.Digest)
518				}
519			}
520		}
521	}
