648	// run calls Seed (with a context that ends the test if the code hangs) and checks
649	// what must hold whatever the outcome.
650	func (e *seedEnv) run() (SeedResult, error) {
651		e.t.Helper()
652		ctx, cancel := context.WithTimeout(context.Background(), provisionTimeout)
653		defer cancel()
654		return e.runWith(ctx)
655	}
656	
657	func (e *seedEnv) runWith(ctx context.Context) (SeedResult, error) {
658		e.t.Helper()
659		var out io.Writer = e.out
660		if e.nilOut {
661			out = nil
662		}
663		e.runs++
664		res, err := Seed(ctx, e.deps, e.b.nexus.URL(), e.p, out)
665		e.checkInvariants(err)
666		return res, err
667	}
