767	// requireNoProgress checks Seed stopped before it touched anything.
768	func (e *seedEnv) requireNoProgress() {
769		e.t.Helper()
770		if len(e.fwd.calls) != 0 {
771			e.t.Errorf("port-forward opened: %+v", e.fwd.calls)
772		}
773		if len(e.cp.copies) != 0 || len(e.cp.digests) != 0 {
774			e.t.Errorf("the copier was used: %d copies, %d reads", len(e.cp.copies), len(e.cp.digests))
775		}
776	}
