778	func requireKind(t *testing.T, err error, kind ErrKind) *BenchError {
779		t.Helper()
780		var be *BenchError
781		if !errors.As(err, &be) {
782			t.Fatalf("error = %#v, want a *BenchError", err)
783		}
784		if be.Kind != kind {
785			t.Fatalf("Kind = %d, want %d; error: %v", be.Kind, kind, err)
