174	// check is what holds after every call, whatever the outcome.
175	func (e *restoreEnv) check(err error) {
176		e.t.Helper()
177		// The cluster: the only write is the scale of bench-upstream.
178		for _, w := range e.kube.writes {
179			if !strings.HasPrefix(w, "scale deployment/"+upstreamName+" ") {
180				e.t.Errorf("write %q is not a scale of %s", w, upstreamName)
181			}
182		}
183		e.kube.requireNoPreflight()
184		// Nexus: always the admin account; the only writes are the PUT and the POST that
185		// put the proxy back in service.
186		for _, r := range e.b.nexus.Requests()[e.baseline:] {
187			if r.User != adminUserID || r.EmptyPassword {
188				e.t.Errorf("request %s %s sent as %q (empty password: %v), want the stored admin", r.Method, r.Path, r.User, r.EmptyPassword)
189			}
190			switch r.Method {
191			case http.MethodGet:
192			case http.MethodPut:
193				if r.Path != repoPath("proxy", dockerProxyRepository) {
194					e.t.Errorf("PUT %s: the restore writes the proxy configuration only", r.Path)
195				}
196			case http.MethodPost:
197				if r.Path != invalidatePath(dockerProxyRepository) {
198					e.t.Errorf("POST %s: the restore invalidates the cache of the proxy only", r.Path)
199				}
200			default:
201				e.t.Errorf("%s %s: the restore deletes nothing", r.Method, r.Path)
202			}
203		}
204		// The copier: nothing is copied; the reads follow F9 and stay on the loopback.
205		if len(e.cp.copies) != 0 {
206			e.t.Errorf("RestoreUpstream copied images: %s", describeCopies(e.cp.copies))
207		}
208		cached := map[string]bool{}
209		for _, img := range pullThrough() {
210			cached[imageArg(nexusImageRef(e.p, dockerProxyRepository, img))] = true
211		}
212		for _, c := range e.cp.digests {
213			if !strings.HasPrefix(c.ref.Location, seedLoopbackHost+":") {
214				e.t.Errorf("read of %s: not on the loopback", imageArg(c.ref))
215			}
216			switch c.where {
217			case whereUpstream:
218				if c.creds != nil {
219					e.t.Errorf("the upstream was read with credentials")
220				}
221			case whereProxy:
222				if !cached[imageArg(c.ref)] {
223					e.t.Errorf("F9: %s was read through docker-proxy, which caches it: only the PullThrough images may be", imageArg(c.ref))
224				}
225				if !sameCreds(c.creds, &e.cp.pull) {
226					e.t.Errorf("the proxy was read with credentials other than bench-pull")
227				}
228			default:
229				e.t.Errorf("read in %q: the restore reads the upstream and docker-proxy only", c.where)
230			}
231		}
232		// One port-forward per run, always stopped.
233		if len(e.fwd.calls) > e.runs {
234			e.t.Errorf("%d port-forwards for %d runs", len(e.fwd.calls), e.runs)
235		}
236		for _, call := range e.fwd.calls {
237			if want := (forwardCall{e.p.Namespace, upstreamName, 5000}); call != want {
238				e.t.Errorf("port-forward to %+v, want %+v", call, want)
239			}
240		}
241		if e.fwd.active {
242			e.t.Error("the port-forward is still open when RestoreUpstream returns")
243		}
244		if opened := e.openedForwards(); e.fwd.stops < opened {
245			e.t.Errorf("%d forwards opened, stop called %d times", opened, e.fwd.stops)
246		}
247		// Progress lines.
248		for _, line := range strings.Split(strings.TrimSpace(e.out.String()), "\n") {
249			if line != "" && !strings.HasPrefix(line, "restore: ") && !strings.HasPrefix(line, "upstream: ") {
250				e.t.Errorf("progress line %q starts with neither restore: nor upstream:", line)
251			}
252		}
253		e.requireQuiet(err)
254	}
