284	func (u *upstreamKubectl) answerDeployments(g getCall, round upstreamRound) ([]byte, []byte, error) {
285		if u.deploymentReply != nil {
286			return u.deploymentReply.reply()
287		}
288		if g.name != "" && g.name != upstreamName {
289			u.t.Errorf("get deployment %q: the upstream lifecycle is about %q only", g.name, upstreamName)
290			return notFoundReply("deployments.apps \"" + g.name + "\"")
291		}
292		if g.selector != "" && g.selector != upstreamSelector {
293			u.t.Errorf("get deployment -l %q: not the upstream", g.selector)
294		}
295		if g.name == upstreamName {
296			if !round.deployment {
297				return notFoundReply("deployments.apps \"" + upstreamName + "\"")
298			}
299			return u.mustJSON(u.deploymentObject(upstreamName, round.replicas, round.pods)), nil, nil
300		}
301		// Nexus first: a reader that takes the first item reads the wrong one.
302		items := []any{u.deploymentObject("nexus", 1, nil)}
303		if round.deployment {
304			items = append(items, u.deploymentObject(upstreamName, round.replicas, round.pods))
305		}
306		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
307	}
