323	func (u *upstreamKubectl) claimObject(name, app, phase string) map[string]any {
324		return map[string]any{
325			"metadata": map[string]any{"name": name, "labels": map[string]string{"app.kubernetes.io/name": app}},
326			"status":   map[string]any{"phase": phase},
327		}
328	}
