364	// scale reads "scale deployment/bench-upstream --replicas=N -n <ns>".
365	func (u *upstreamKubectl) scale(norm []string) ([]byte, []byte, error) {
366		var call scaleCall
367		var positional []string
368		for i := 1; i < len(norm); i++ {
369			switch a := norm[i]; {
370			case a == "-n" || a == "--namespace":
371				i++
372				call.namespace = at(norm, i)
373			case strings.HasPrefix(a, "--replicas="):
374				call.replicas = strings.TrimPrefix(a, "--replicas=")
375			case strings.HasPrefix(a, "--timeout=") || strings.HasPrefix(a, "--current-replicas="):
376			case strings.HasPrefix(a, "-"):
377				u.t.Errorf("unscripted argument %q in %q", a, norm)
378			default:
379				positional = append(positional, a)
380			}
381		}
382		call.resource = strings.Join(positional, "/")
383		u.scales = append(u.scales, call)
384		if call.resource != "deployment/"+upstreamName && call.resource != "deployments/"+upstreamName && call.resource != "deploy/"+upstreamName {
385			u.t.Errorf("scale targets %q, want deployment/%s: the upstream is the only thing to scale", call.resource, upstreamName)
386			return nil, []byte("the fake refuses this scale"), errFakeExit1
387		}
388		if call.namespace != u.p.Namespace {
389			u.t.Errorf("scale in namespace %q, the run is about %q", call.namespace, u.p.Namespace)
390		}
391		if u.scaleReply != nil {
392			return u.scaleReply.reply()
393		}
394		if call.replicas == "" {
395			u.t.Errorf("scale without --replicas: %q", norm)
396		}
397		u.scaledAt = len(u.clk.sleeps)
398		return []byte("deployment.apps/" + upstreamName + " scaled\n"), nil, nil
399	}
