170	func (u *upstreamKubectl) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
171		norm := normalizeArgs(args)
172		joined := strings.Join(norm, " ")
173		u.lines = append(u.lines, joined)
174		verb := verbOf(args)
175		if isWriteVerb(verb) {
176			u.writes = append(u.writes, joined)
177		}
178		switch {
179		case verb == "scale":
180			return u.scale(norm)
181		case isWriteVerb(verb):
182			u.t.Errorf("unexpected write call %q: the upstream is only scaled", args)
183			return nil, []byte("the fake refuses a write: " + verb), errFakeExit1
184		case verb == "get":
185			if g, ok := u.parseGet(norm); ok {
186				return u.answer(g)
187			}
188		}
189		return u.fakeKubectl.Run(ctx, stdin, args...)
190	}
