196	// kindOfResource maps the spellings of kubectl to one name; "" is unknown.
197	func kindOfResource(r string) string {
198		switch r {
199		case "deployment", "deployments", "deploy", "deployment.apps", "deployments.apps":
200			return "deployment"
201		case "pod", "pods", "po":
202			return "pod"
203		case "pvc", "persistentvolumeclaim", "persistentvolumeclaims":
204			return "pvc"
205		}
206		return ""
207	}
